import urllib.request
from html.parser import HTMLParser
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.items=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip=max(0,self.skip-1)
 def handle_data(self,d):
  if not self.skip and d.strip(): self.items.append(d.strip())
for u in ['https://www.life.uestc.edu.cn/info/1166/7359.htm','https://bme-college.fudan.edu.cn/f4/5f/c49155a783455/page.psp','http://www.cbeis.zju.edu.cn/']:
 print('URL:',u)
 try:
  req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0'})
  with urllib.request.urlopen(req,timeout=15) as r: raw=r.read().decode('utf-8','replace')
  p=Text(); p.feed(raw); content='\\n'.join(p.items)
  print(content[:14000])
 except Exception as e: print(type(e).__name__,str(e))
